(function() {
    // Avoid running multiple times on the same element
    if (element.dataset.sidebarMoved === 'true') return;

    var helpguide = document.getElementById('helpguide');
    if (!helpguide) return;

    // Clone and move the need-more-help-container to the sidebar
    var movedContainer = element.cloneNode(true);
    movedContainer.style.display = 'block';
    movedContainer.style.position = 'sticky';
    movedContainer.style.top = '16px';
    movedContainer.style.width = '280px';
    movedContainer.style.padding = '16px';
    movedContainer.style.marginLeft = '16px';
    movedContainer.style.flexShrink = '0';

    helpguide.appendChild(movedContainer);
    helpguide.style.display = 'block';

    // Make page-width-container a flex container to put sidebar next to main content
    var pageWidth = document.getElementById('page-width-container');
    if (pageWidth) {
        pageWidth.style.display = 'flex';
        pageWidth.style.flexDirection = 'row';
    }

    // Ensure main-content doesn't take all space
    var mainContent = document.querySelector('.main-content');
    if (mainContent) {
        mainContent.style.flex = '1';
        mainContent.style.minWidth = '0';
    }

    // Hide the original by collapsing it
    element.style.display = 'none';
    element.dataset.sidebarMoved = 'true';
})();
